import json as _json

seq = int(bindings.get('chunk_seq_now') or 0)
item = next((c for c in (bindings.get('chunk_items') or []) if int(c.get('seq') or 0) == seq), None) or {}
kw_topn = int(item.get('kw_topn') or 0)
q_topn = int(item.get('q_topn') or 0)

kw = bindings.get('chunk_kw_llm')
if kw_topn >= 1:
    if not isinstance(kw, list):
        kw = list(item.get('doc_kw') or [])
    kw = [str(k) for k in kw][:kw_topn]
else:
    kw = list(item.get('doc_kw') or [])[:kw_topn] if kw_topn else []

q = bindings.get('chunk_q_llm')
if q_topn >= 1:
    if not isinstance(q, list):
        q = []
    q = [str(x) for x in q][:q_topn]
else:
    q = []

map_ = bindings.setdefault('enhance_map', {})
map_[str(seq)] = {'keywords': kw, 'questions': q}

# 清空当前片临时变量（防下轮残留）
for k in ('kw_prompt', 'q_prompt', 'chunk_kw_llm', 'chunk_q_llm', 'chunk_seq_now'):
    bindings.pop(k, None)

# 末轮判定：全部切片已收集 → 汇总 enhancement
items = bindings.get('chunk_items') or []
done = all(str(c.get('seq') or 0) in map_ for c in items)
if done:
    doc_meta = bindings.get('doc_meta') or {}
    chunks_out = []
    for c in items:
        s = str(c.get('seq') or 0)
        e = map_.get(s) or {}
        chunks_out.append({
            'seq': int(c.get('seq') or 0),
            'keywords': e.get('keywords') or [],
            'questions': e.get('questions') or [],
        })
    enhancement = {
        'title': str(bindings.get('doc_title') or ''),
        'abstract': str(doc_meta.get('summary') or bindings.get('doc_summary') or ''),
        'doc_keywords': list(doc_meta.get('keywords') or []),
        'chunks': chunks_out,
    }
    bindings['enhancement'] = enhancement
    with open('/tmp/chunk_enhance.json', 'w', encoding='utf-8') as f:
        _json.dump(enhancement, f, ensure_ascii=False, indent=1)
    print('[n4e] 增强完成: %d 片, 含关键词 %d, 含问题 %d'
          % (len(chunks_out),
             sum(1 for c in chunks_out if c['keywords']),
             sum(1 for c in chunks_out if c['questions'])))

